-- Additive admissions, evidence, notifications and controlled content publishing.
create table private.content_admins(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
alter table private.content_admins enable row level security;
revoke all on private.content_admins from public,anon,authenticated;
insert into private.content_admins(user_id) select id from auth.users where email='erm1ham3d2604@gmail.com' and email_confirmed_at is not null and not is_anonymous on conflict do nothing;
create function public.is_content_admin() returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from private.content_admins where user_id=auth.uid());$$;
revoke all on function public.is_content_admin() from public,anon;grant execute on function public.is_content_admin() to authenticated;
create table public.intelligence_records(id text primary key check(length(id) between 2 and 120),kind text not null check(kind in ('university','course','scholarship','opportunity','professional','project','research','pathway','location','cv')),payload jsonb not null check(jsonb_typeof(payload)='object' and octet_length(payload::text)<100000),status text not null default 'Published' check(status in ('Published','Archived')),checked_on date not null,version integer not null default 1 check(version>0),updated_at timestamptz not null default now());
create index intelligence_kind_status_idx on public.intelligence_records(kind,status,checked_on);
alter table public.intelligence_records enable row level security;revoke all on public.intelligence_records from anon,authenticated;grant select,insert,update on public.intelligence_records to authenticated;
create policy "Signed in catalog read" on public.intelligence_records for select to authenticated using(not coalesce((auth.jwt()->>'is_anonymous')::boolean,false));
create policy "Admin content insert" on public.intelligence_records for insert to authenticated with check((select public.is_content_admin()));
create policy "Admin content update" on public.intelligence_records for update to authenticated using((select public.is_content_admin())) with check((select public.is_content_admin()));
create table public.content_versions(id bigint generated always as identity primary key,record_id text not null,version integer not null,before_payload jsonb,after_payload jsonb,old_status text,new_status text,actor uuid,changed_at timestamptz not null default now(),unique(record_id,version));
create index content_versions_record_idx on public.content_versions(record_id,version desc);
alter table public.content_versions enable row level security;revoke all on public.content_versions from anon,authenticated;grant select on public.content_versions to authenticated;create policy "Admin history read" on public.content_versions for select to authenticated using((select public.is_content_admin()));
create function private.audit_content_change() returns trigger language plpgsql security definer set search_path='' as $$begin
 if tg_op='UPDATE' then new.version:=old.version+1;new.updated_at:=now();end if;
 insert into public.content_versions(record_id,version,before_payload,after_payload,old_status,new_status,actor) values(new.id,new.version,case when tg_op='UPDATE' then old.payload else null end,new.payload,case when tg_op='UPDATE' then old.status else null end,new.status,auth.uid());return new;end $$;
revoke all on function private.audit_content_change() from public,anon,authenticated;
create trigger intelligence_audit before insert or update on public.intelligence_records for each row execute function private.audit_content_change();
create table public.content_candidates(id uuid primary key default gen_random_uuid(),record_id text,source_url text not null check(length(source_url)<2000),proposal jsonb not null check(jsonb_typeof(proposal)='object' and octet_length(proposal::text)<100000),state text not null default 'Review' check(state in ('Review','Approved','Rejected')),notes text not null default '' check(length(notes)<2000),created_at timestamptz not null default now());
alter table public.content_candidates enable row level security;revoke all on public.content_candidates from anon,authenticated;grant select,insert,update on public.content_candidates to authenticated;
create policy "Admin candidate select" on public.content_candidates for select to authenticated using((select public.is_content_admin()));create policy "Admin candidate insert" on public.content_candidates for insert to authenticated with check((select public.is_content_admin()));create policy "Admin candidate update" on public.content_candidates for update to authenticated using((select public.is_content_admin())) with check((select public.is_content_admin()));
create function public.publish_intelligence(record jsonb,expected_version integer) returns integer language plpgsql security invoker set search_path='' as $$declare current_version integer;new_version integer;begin
 if not public.is_content_admin() then raise exception 'Administrator access required.';end if;
 perform pg_advisory_xact_lock(hashtextextended(record->>'id',48201));
 select version into current_version from public.intelligence_records where id=record->>'id' for update;
 if coalesce(current_version,0) is distinct from expected_version then raise exception 'This record changed. Reload before publishing.';end if;
 if current_version is null then
 insert into public.intelligence_records(id,kind,payload,status,checked_on) values(record->>'id',record->>'kind',record,case when record->>'status'='Archived' then 'Archived' else 'Published' end,(record->>'checkedOn')::date) returning version into new_version;
 else update public.intelligence_records set kind=record->>'kind',payload=record,status=case when record->>'status'='Archived' then 'Archived' else 'Published' end,checked_on=(record->>'checkedOn')::date where id=record->>'id' returning version into new_version;end if;
 return new_version;end $$;
revoke all on function public.publish_intelligence(jsonb,integer) from public,anon;grant execute on function public.publish_intelligence(jsonb,integer) to authenticated;
create table public.admissions_folders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,university_id text not null check(length(university_id)<120),title text not null check(length(title) between 1 and 200),stage text not null default 'Researching' check(stage in ('Researching','Preparing','Applying','Submitted','Interview','Decision','Archived')),notes text not null default '' check(length(notes)<5000),created_at timestamptz not null default now(),unique(id,user_id),unique(user_id,university_id));
create table public.admissions_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,folder_id uuid not null,kind text not null check(kind in ('Programme','Task','Essay','Question','Interview','Scholarship','Decision factor','Official link')),title text not null check(length(title) between 1 and 200),body text not null default '' check(length(body)<=30000),url text check(length(url)<2000),due_date date,completed boolean not null default false,created_at timestamptz not null default now(),foreign key(folder_id,user_id) references public.admissions_folders(id,user_id) on delete cascade);
create table public.folder_documents(user_id uuid not null references auth.users(id) on delete cascade,folder_id uuid not null,document_id uuid not null,primary key(user_id,folder_id,document_id),foreign key(folder_id,user_id) references public.admissions_folders(id,user_id) on delete cascade,foreign key(document_id,user_id) references public.documents(id,user_id) on delete cascade);
create table public.saved_resources(user_id uuid not null references auth.users(id) on delete cascade,resource_id text not null check(length(resource_id) between 1 and 120),kind text not null check(length(kind)<50),title text not null check(length(title) between 1 and 200),notes text not null default '' check(length(notes)<4000),saved_at timestamptz not null default now(),primary key(user_id,resource_id));
create table public.evidence_links(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,target_kind text not null check(target_kind in ('skill','course','project','pathway')),target_id text not null check(length(target_id)<120),record_id uuid references public.profile_records(id) on delete set null,document_id uuid,course_id text,project_id text,notes text not null default '' check(length(notes)<=2000),created_at timestamptz not null default now(),foreign key(document_id,user_id) references public.documents(id,user_id) on delete cascade);
create function public.check_evidence_owner() returns trigger language plpgsql security invoker set search_path='' as $$begin if new.record_id is not null and not exists(select 1 from public.profile_records where id=new.record_id and user_id=new.user_id) then raise exception 'Evidence is not in your workspace.';end if;return new;end $$;
create trigger evidence_owner before insert or update on public.evidence_links for each row execute function public.check_evidence_owner();revoke all on function public.check_evidence_owner() from public,anon,authenticated;
create table public.notification_states(user_id uuid not null references auth.users(id) on delete cascade,notice_key text not null check(length(notice_key)<180),state text not null check(state in ('Dismissed','Snoozed','Read')),snooze_until timestamptz,updated_at timestamptz not null default now(),primary key(user_id,notice_key));
create index admissions_items_owner_folder_idx on public.admissions_items(user_id,folder_id,due_date);create index admissions_folders_owner_idx on public.admissions_folders(user_id);create index evidence_owner_target_idx on public.evidence_links(user_id,target_kind,target_id);create index evidence_record_idx on public.evidence_links(record_id);create index folder_documents_document_idx on public.folder_documents(document_id,user_id);
do $$declare t text;begin foreach t in array array['admissions_folders','admissions_items','folder_documents','saved_resources','evidence_links','notification_states'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to authenticated',t);execute format('create policy "Owner read" on public.%I for select to authenticated using((select auth.uid())=user_id)',t);execute format('create policy "Owner insert" on public.%I for insert to authenticated with check((select auth.uid())=user_id)',t);execute format('create policy "Owner update" on public.%I for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id)',t);execute format('create policy "Owner delete" on public.%I for delete to authenticated using((select auth.uid())=user_id)',t);end loop;end $$;
alter table public.user_skills drop constraint user_skills_state_check;
update public.user_skills set state='Practising' where state='Developing';
alter table public.user_skills add constraint user_skills_state_check check(state in ('Not started','Exploring','Learning','Practising','Demonstrated','Verified by evidence'));
alter table public.user_skills add constraint skill_verified_evidence check(state<>'Verified by evidence' or length(trim(evidence))>0);
alter table public.course_progress add column project_id text check(length(project_id)<120),add column evidence text not null default '' check(length(evidence)<=2000);
-- Archive known expired published cycles without deleting saved user history.
select cron.schedule('prospectoai-daily-content-expiry','15 0 * * *',$job$update public.intelligence_records set status='Archived' where kind in ('opportunity','scholarship') and status='Published' and payload->>'finalDeadline' ~ '^\d{4}-\d{2}-\d{2}$' and (payload->>'finalDeadline')::date<current_date;$job$);
